import{_ as o,c as a,a0 as c,o as d}from"./chunks/framework.B6JXc2q-.js";const _=JSON.parse('{"title":"PlaybackCoordinator 接口约束","description":"","frontmatter":{},"headers":[],"relativePath":"spec/playback/playback_coordinator_interface.md","filePath":"spec/playback/playback_coordinator_interface.md"}'),t={name:"spec/playback/playback_coordinator_interface.md"};function r(i,e,l,s,n,p){return d(),a("div",null,e[0]||(e[0]=[c('<h1 id="playbackcoordinator-接口约束" tabindex="-1">PlaybackCoordinator 接口约束 <a class="header-anchor" href="#playbackcoordinator-接口约束" aria-label="Permalink to &quot;PlaybackCoordinator 接口约束&quot;">​</a></h1><blockquote><p>状态：现行内部接口 最后核对：2026-09-28 实现：<code>xiaomusic/core/coordinator/playback_coordinator.py</code></p></blockquote><h2 id="_1-作用" tabindex="-1">1. 作用 <a class="header-anchor" href="#_1-作用" aria-label="Permalink to &quot;1. 作用&quot;">​</a></h2><p><code>PlaybackCoordinator</code> 编排 Source 解析、delivery plan、transport 分派与一次受控的过期流重解析。它不拥有歌单事实，也不直接定义 Public API 响应。</p><h2 id="_2-依赖" tabindex="-1">2. 依赖 <a class="header-anchor" href="#_2-依赖" aria-label="Permalink to &quot;2. 依赖&quot;">​</a></h2><p>构造时注入：</p><ul><li><code>SourceRegistry</code>：根据 <code>source_hint</code> 与请求选择插件</li><li><code>DeviceRegistry</code>：读取设备 profile 与能力矩阵</li><li><code>DeliveryAdapter</code>：把 <code>ResolvedMedia</code> 转为 direct / proxy plan</li><li><code>TransportRouter</code>：下发播放与控制动作</li><li>可选 <code>playback_status_provider</code>：确认设备是否实际开始播放</li></ul><p>Coordinator 不接收完整 <code>XiaoMusic</code> runtime。</p><h2 id="_3-输入与输出" tabindex="-1">3. 输入与输出 <a class="header-anchor" href="#_3-输入与输出" aria-label="Permalink to &quot;3. 输入与输出&quot;">​</a></h2><h3 id="play-request-mediarequest-device-id-str-none-none-dict" tabindex="-1"><code>play(request: MediaRequest, device_id: str | None = None) -&gt; dict</code> <a class="header-anchor" href="#play-request-mediarequest-device-id-str-none-none-dict" aria-label="Permalink to &quot;`play(request: MediaRequest, device_id: str | None = None) -&gt; dict`&quot;">​</a></h3><ul><li><code>device_id</code> 必须由参数或 <code>request.device_id</code> 提供。</li><li>Source 返回 <code>ResolvedMedia</code>；delivery 返回 <code>DeliveryPlan</code>；transport 返回 dispatch result。</li><li>结果包含 <code>request_id</code>、<code>transport</code>、<code>prepared_stream</code>、<code>resolved_media</code>、<code>dispatch</code>、<code>delivery_plan</code> 与 <code>outcome</code>。</li><li><code>ExpiredStreamError</code> 最多按 <code>max_resolve_retry</code> 重做解析；其他错误不在 coordinator 内扩散重试。</li></ul><h3 id="resolve-request-mediarequest-dict" tabindex="-1"><code>resolve(request: MediaRequest) -&gt; dict</code> <a class="header-anchor" href="#resolve-request-mediarequest-dict" aria-label="Permalink to &quot;`resolve(request: MediaRequest) -&gt; dict`&quot;">​</a></h3><p>只执行 Source 解析，不下发设备命令。</p><h3 id="控制方法" tabindex="-1">控制方法 <a class="header-anchor" href="#控制方法" aria-label="Permalink to &quot;控制方法&quot;">​</a></h3><p><code>stop</code>、<code>previous</code>、<code>next</code>、<code>pause</code>、<code>resume</code>、<code>tts</code>、<code>set_volume</code>、<code>probe</code> 统一经 <code>TransportRouter</code>。<code>resume</code> 当前通过 transport 的 pause toggle 兼容实现。</p><h2 id="_4-状态投影边界" tabindex="-1">4. 状态投影边界 <a class="header-anchor" href="#_4-状态投影边界" aria-label="Permalink to &quot;4. 状态投影边界&quot;">​</a></h2><p>Coordinator 的返回值是内部编排结果，不等于 <code>/api/v1/player/state</code>。Public 状态由 <code>PlaybackFacade</code> 从设备运行态构建，并遵守 <code>player_state_projection_spec.md</code>：</p><ul><li><code>track.id</code> 使用后端稳定 identity，不使用 <code>context_id + title</code> 的旧组合哈希规则；</li><li><code>context</code> 保持对象结构，不展开为 <code>context_type/context_id/context_name</code> 顶层字段；</li><li><code>accepted</code> 与 <code>started</code> 分离，命令被接收不代表设备已经播放；</li><li>WebUI 不直接消费 Coordinator 原始对象。</li></ul><h2 id="_5-验证依据" tabindex="-1">5. 验证依据 <a class="header-anchor" href="#_5-验证依据" aria-label="Permalink to &quot;5. 验证依据&quot;">​</a></h2><ul><li><code>tests/unit/test_core_playback_coordinator.py</code></li><li><code>tests/unit/test_core_source_plugins_and_registry.py</code></li><li><code>tests/unit/test_core_transport_router.py</code></li><li><code>tests/unit/test_playback_facade.py</code></li><li><code>docs/spec/player_state_projection_spec.md</code></li></ul>',20)]))}const h=o(t,[["render",r]]);export{_ as __pageData,h as default};
